  then
    echo "FAILED to sign the shortcut: no answer from HubSign."
  elif [ "$(head -c 4 aria2.shortcut.new)" = AEA1 ]; then
    mv -f aria2.shortcut.new aria2.shortcut
    echo 3-1155b9e4 >.version
    new_shortcut=/root/Shortcuts/aria2.shortcut
    # Also into the Files folder mounted at /mnt/phone, always as aria2.shortcut, in place
    # of the one before: copied in under another name first, because writing into a file
    # that Files has open there can hang. Builds before used to be aria2-<version>.shortcut.
    if awk '$2 == "/mnt/phone" { found = 1 } END { exit !found }' /proc/mounts 2>/dev/null; then
      timeout 60 rm -f /mnt/phone/aria2-*.shortcut
      if timeout 60 cp aria2.shortcut /mnt/phone/.aria2.shortcut.new &&
          timeout 60 mv -f /mnt/phone/.aria2.shortcut.new /mnt/phone/aria2.shortcut; then
        new_shortcut=/mnt/phone/aria2.shortcut
      fi
    fi
    # The shortcut, when it next opens, offers the new one by itself. dl's menu shows it
    # until the new shortcut has been imported, which it can tell from the version.
    echo "$new_shortcut" >.pending
    echo "Signed the new aria2 shortcut."
  else
    echo "FAILED to sign the shortcut: $(head -c 300 aria2.shortcut.new)"
  fi
  rm -f /root/Shortcuts/aria2.shortcut.new
fi
cd /root || exit 1
[ -n "$awake" ] && kill $awake 2>/dev/null

echo
dl -v

echo
echo "Setup finished."
case $new_shortcut in
  /mnt/phone/*) echo "Next: in Files, open the folder you mounted at /mnt/phone and tap aria2.shortcut." ;;
  /root/*) echo "Next: in Files, tap iSH-AOK -> (Alpine) -> root -> Shortcuts -> aria2.shortcut." ;;
esac
[ -n "$new_shortcut" ] && echo "Add it, or choose Replace if you already have the aria2 shortcut."
cat <<'DONE'
If you haven't yet: Settings -> Apps -> iSH-AOK -> Location: choose Always, and turn
Precise Location off to save battery. Without Always, downloads only run while iSH-AOK is open.
DONE
